from bs4 import BeautifulSoup
import json, pathlib, sys
root=pathlib.Path(sys.argv[1])/'details'
counts={}
missing=[]
for path in sorted(root.glob('*.html')):
    soup=BeautifulSoup(path.read_text(errors='replace'),'html.parser')
    data=[]
    for s in soup.find_all('script', type='application/ld+json'):
        try:
            obj=json.loads(s.string or s.get_text())
        except Exception:
            continue
        if isinstance(obj, dict) and obj.get('@type')=='Course': data.append(obj)
        elif isinstance(obj, list): data.extend(x for x in obj if isinstance(x,dict) and x.get('@type')=='Course')
    if not data:
        missing.append(path.name); continue
    obj=data[0]
    mode=obj.get('hasCourseInstance',{}).get('courseMode') if isinstance(obj.get('hasCourseInstance'),dict) else None
    counts[mode]=counts.get(mode,0)+1
print('course_jsonld', sum(counts.values()), 'missing_jsonld', len(missing), 'modes', counts)
print('missing', missing[:20])
PY"

